//! Auto-generated virtualizable infrastructure for `PyFrame`.
//!
//! Generated by `majit_macros::virtualizable!` from the canonical field
//! declaration. Provides layout-based JitState helpers, VirtualizableInfo
//! builder, field/array spec constants, and virtualizable hook helpers.

use crate::frame_layout::{
    PYFRAME_DEBUGDATA_OFFSET, PYFRAME_LAST_INSTR_OFFSET, PYFRAME_LOCALS_CELLS_STACK_OFFSET,
    PYFRAME_PYCODE_OFFSET, PYFRAME_VABLE_TOKEN_OFFSET, PYFRAME_VALUESTACKDEPTH_OFFSET,
};
use crate::state::PyreJitState;
use pyre_object::FIXED_OBJECT_ARRAY_TOKEN;

majit_macros::virtualizable! {
    state = PyreJitState,
    name = "frame",
    heap_ptr = |s: &PyreJitState| { let p = s.live_frame(); if p != 0 { p as *mut u8 } else { std::ptr::null_mut() } },
    token_offset = PYFRAME_VABLE_TOKEN_OFFSET,

    // Frame pointer field in PyreJitState
    frame_field = frame,

    // Non-vable JitDriver reds (`interp_jit.py reds = ['frame', 'ec']`).
    // `frame` is implicit at OpRef::from_raw(0); each entry here shifts
    // `NUM_SCALAR_INPUTARGS` and `SYM_ARRAY_BASE` by one and occupies
    // `OpRef(1..1+NUM_EXTRA_REDS)` between frame and the vable static
    // fields.
    extra_reds = {
        ec: Ref,
    },

    // Layout: [frame:Ref, ec:Ref, last_instr:Int, pycode:Ref,
    //          valuestackdepth:Int, debugdata:Ref, array...]
    // Mirrors the concrete fields `InstanceRepr._parse_field_list` selects
    // from `pypy/module/pypyjit/interp_jit.py`'s `PyFrame._virtualizable_`;
    // its stale `w_globals` name has no PyFrame field and is skipped. `ec` is
    // from `interp_jit.py reds = ['frame', 'ec']` (extra_reds above).
    inputargs = {
        last_instr: Int,
        pycode: Ref,
        valuestackdepth: Int,
        debugdata: Ref,
    },

    // Array items are PyObjectRef (Ref)
    array_item_type = Ref,

    // VirtualizableInfo field layout (byte offsets).
    // interp_jit.py:25-30 order — line-by-line PyPy parity.
    fields = {
        last_instr: int @ PYFRAME_LAST_INSTR_OFFSET,
        pycode: ref @ PYFRAME_PYCODE_OFFSET,
        valuestackdepth: int @ PYFRAME_VALUESTACKDEPTH_OFFSET,
        debugdata: ref @ PYFRAME_DEBUGDATA_OFFSET,
    },

    // RPython virtualizable.py:28 parity: the array field holds a pointer
    // to a `Ptr(GcArray(PyObjectRef))` whose header is `[len][items...]`.
    // So GETFIELD_GC_R(frame, locals_cells_stack) + GETARRAYITEM_GC_R(p, i)
    // with the items offset as `base_size` reads items[i] directly, no
    // container indirection. Both offsets come from the block struct's
    // `get_array_token` (`FixedObjectArray`).
    arrays = {
        locals_cells_stack_w: ref @ PYFRAME_LOCALS_CELLS_STACK_OFFSET {
            length_offset: FIXED_OBJECT_ARRAY_TOKEN.len_offset,
            items_offset: FIXED_OBJECT_ARRAY_TOKEN.base_size,
        },
    },
}
